mapper.select:
SELECT t.*, c.name as category_name, c.icon as category_icon
FROM `transaction` t
LEFT JOIN category c ON t.category_id = c.id
WHERE t.user_id = #{userId} AND t.deleted = 0

    AND t.transaction_date >= #{startDate}


    AND t.transaction_date <= #{endDate}


    AND t.type = #{type}


    AND t.category_id = #{categoryId}

ORDER BY t.transaction_date DESC, t.create_time DESC

SELECT c.name as name, c.icon as icon, SUM(t.amount) as value
FROM `transaction` t
LEFT JOIN category c ON t.category_id = c.id
WHERE t.user_id = #{userId} AND t.deleted = 0 AND t.type = #{type}

    AND t.transaction_date >= #{startDate}


    AND t.transaction_date <= #{endDate}

GROUP BY t.category_id
ORDER BY value DESC

SELECT DATE_FORMAT(t.transaction_date, '%Y-%m-%d') as date, SUM(CASE WHEN t.type = 1 THEN t.amount ELSE 0 END) as income, SUM(CASE WHEN t.type = 2 THEN t.amount ELSE 0 END) as expense FROM `transaction` t WHERE t.user_id = #{userId} AND t.deleted = 0
AND t.transaction_date >= #{startDate}
AND t.transaction_date <= #{endDate}
GROUP BY DATE_FORMAT(t.transaction_date, '%Y-%m-%d') ORDER BY date
